const input=$json;
const canonicalChoices=['QUER_FECHAR','QUER_PENSAR','PEDIU_DESCONTO','TEM_DUVIDA','DESISTIU','HUMANO','INDEFINIDO'];
const aliases={
  'ACEITOU':'QUER_FECHAR',
  'QUER_CONTRATAR':'QUER_FECHAR',
  'PRECISA_HUMANO':'HUMANO'
};
const rawChoice=String(input.jev_choice ?? input.choice ?? '').trim().toUpperCase();

if(!rawChoice){
  return {json:{
    contract_version:'1.0.0',
    status:'model_required',
    decision:null,
    allowed_choices:canonicalChoices,
    model_request:{
      action:'CALL_JEV',
      stage:input.commercial_stage ?? null,
      message:input.message ?? '',
      allowed_choices:canonicalChoices
    },
    next_action:null,
    blockers:['JEV_NOT_CONNECTED']
  }};
}

const choice=aliases[rawChoice] ?? rawChoice;
if(!canonicalChoices.includes(choice)){
  return {json:{
    contract_version:'1.0.0',
    status:'human_required',
    decision:null,
    allowed_choices:canonicalChoices,
    model_request:null,
    next_action:{action:'HANDOFF_HUMANO',reason_code:'JEV_CHOICE_OUT_OF_VOCABULARY',force_lock:true},
    blockers:['JEV_CHOICE_OUT_OF_VOCABULARY']
  }};
}

const routes={
  'QUER_FECHAR':{action:'REQUEST_CLOSING'},
  'QUER_PENSAR':{action:'RESPONDER_AGUARDAR_DECISAO'},
  'PEDIU_DESCONTO':{action:'HANDOFF_HUMANO',reason_code:'BARGAIN',force_lock:true},
  'TEM_DUVIDA':{action:'RESPONDER_DUVIDA'},
  'DESISTIU':{action:'PROPOSE_LOSS',loss_reason_type:'explicit'},
  'HUMANO':{action:'HANDOFF_HUMANO',reason_code:'SEMANTIC_HUMAN',force_lock:true},
  'INDEFINIDO':{action:'ASK_ONE_CLARIFYING_QUESTION'}
};

return {json:{
  contract_version:'1.0.0',
  status:'ready',
  decision:choice,
  allowed_choices:canonicalChoices,
  model_request:null,
  next_action:routes[choice],
  blockers:[]
}};
